def translate(name):
    text=name.lower().replace('’',"'").replace('-',' ')
    for phrase,zh in sorted(PHRASES.items(),key=lambda x:-len(x[0])):
        text=re.sub(r'\b'+re.escape(phrase.replace('-',' '))+r'\b',zh,text)
    missing=[]
    def replace(match):
        word=match.group();
        if word not in wordmap:missing.append(word);return word
        return wordmap[word]
    text=re.sub('[a-z]+',replace,text)
    if missing:raise ValueError(name+' -> '+str(missing))
    text=re.sub(r'\s+','',text).replace('(', '（').replace(')','）')
    text=text.replace('（（','（').replace('））','）').replace('臂屈伸三头肌','三头肌臂屈伸')
    return text
def build():
    raw=json.loads((ROOT/'data/raw/exercise-names.json').read_text(encoding='utf-8'))
    old=json.loads((ROOT/'frontend/src/data/exercise-names.json').read_text(encoding='utf-8'))
    result={};errors=[]
    for e in raw:
        prior=old.get(e['id'],{})
        try:name=prior['nameZh'] if prior.get('translationSource')=='manual' else translate(e['name'])
        except ValueError as error:errors.append(str(error));continue
        result[e['id']]={**prior,'nameZh':name,'nameEn':e['name'],'translationSource':'manual' if prior.get('translationSource')=='manual' else 'curated-terminology'}
    if errors:raise ValueError('\n'.join(errors))
    (ROOT/'frontend/src/data/exercise-names.json').write_text(json.dumps(result,ensure_ascii=False,separators=(',',':')),encoding='utf-8')
    print('Chinese exercise names: '+str(len(result))+'; no unresolved English tokens or placeholders')
if __name__=='__main__':build()
